/* Ponlo en false cuando el backend entregue el TRAMA Index real: el flujo
   volverá a mandar al error de validación cualquier diagnóstico sin índice. */
const CALCULO_PROVISIONAL = true;

const j = $input.first().json || {};
const cfg = $('Preparar configuración').first().json;

/* Lo que venga del backend (o de los datos de prueba) manda siempre. */
let indice = typeof j.trama_index === "number" ? j.trama_index
  : (typeof j.score === "number" ? j.score : null);
if (indice !== null && !Number.isFinite(indice)) indice = null;

let provisional = false;
const puntuadas = {};

if (indice === null && CALCULO_PROVISIONAL) {
  /* Las respuestas llegan como etiquetas —«Casi siempre»—, no como números.
     Cada pregunta trae de la hoja su tabla de etiqueta a valor, y cada escala
     su propio mínimo y máximo. Se normaliza pregunta a pregunta y se promedia,
     así una escala de 1 a 5 y otra de 0 a 1 pesan igual y nadie tiene que
     acordarse de reajustar nada al añadir una escala nueva. */
  const normalizados = [];

  for (const p of cfg.preguntas || []) {
    const dado = j[p.id];
    if (dado === undefined || dado === null || String(dado).trim() === "") continue;

    let valor = p.valores ? p.valores[String(dado)] : undefined;
    if (valor === undefined || valor === null) {
      const n = Number(dado);
      valor = Number.isFinite(n) ? n : undefined;
    }
    if (valor === undefined || valor === null) continue;

    const escala = Object.values(p.valores || {}).filter((v) => Number.isFinite(v));
    if (escala.length < 2) continue;
    const min = Math.min.apply(null, escala);
    const max = Math.max.apply(null, escala);
    if (max === min) continue;

    puntuadas[p.id] = valor;
    normalizados.push((valor - min) / (max - min));
  }

  if (normalizados.length) {
    indice = Math.round((normalizados.reduce((a, b) => a + b, 0) / normalizados.length) * 100);
    provisional = true;
  }
}

return [{
  json: {
    ...j,
    trama_index: indice,
    trama_index_provisional: provisional,
    respuestas_puntuadas: puntuadas,
    calculo_pendiente: indice === null,
    nota_calculo: provisional
      ? "PROVISIONAL: media normalizada de las respuestas segun la escala de cada pregunta. No es la formula TRAMA. [pendiente: formula, dimensiones y ponderaciones reales]"
      : "[pendiente: formula, dimensiones y ponderaciones del TRAMA Index]",
  },
  pairedItem: { item: 0 },
}];

// [pendiente: fórmula o criterio exacto para calcular el porcentaje de coherencia (objetivo > 90%)]
// Interpretación provisional y marcada como pendiente: se considera coherente solo si la
// respuesta NO está malformada (tiene texto). El umbral real > 90% queda pendiente de fórmula.
const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json || {};
  let texto = "";
  if (Array.isArray(j.content) && j.content[0] && j.content[0].text) {
    texto = j.content[0].text;
  } else if (typeof j.text === "string") {
    texto = j.text;
  }
  const malformado = texto === "";
  const intento = $runIndex; // 0 = primer intento; 1 y 2 = reinterpretaciones automáticas
  const es_coherente = !malformado; // [pendiente] hasta definir la fórmula real de coherencia
  out.push({ json: {
    es_prueba: j.es_prueba === true || $('Preparar Interpretación').first().json.es_prueba === true,
    recomendaciones: texto,
    malformado: malformado,
    intento: intento,
    coherencia_pct: null,
    es_coherente: es_coherente,
    pendiente_coherencia: "[pendiente: fórmula o criterio exacto para calcular el porcentaje de coherencia]"
  } });
}
return out;

/* Aquí solo se elige el escenario. Las respuestas las rellena «Preparar
   configuración», que es el único que sabe cuántas preguntas hay en la hoja y
   cómo se llaman: si mañana son veinte, la prueba sigue completa sola.

